const express = require('express');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const os = require('os');

const app = express();
app.use(express.json());

// Cross-service authentication via HMAC
const SERVICE_SECRETS = {
  'model-trainer': Buffer.from(process.env.TRAINER_SECRET || 'dev-secret-trainer', 'utf8'),
  'data-pipeline': Buffer.from(process.env.PIPELINE_SECRET || 'dev-secret-pipeline', 'utf8'),
  'api-gateway': Buffer.from(process.env.GATEWAY_SECRET || 'dev-secret-gateway', 'utf8')
};

const MODEL_BASE_DIR = process.env.MODEL_DIR || '/var/ml-models';
const CACHE_DIR = path.join(os.tmpdir(), 'ml-inference-cache');

// Ensure cache directory exists
if (!fs.existsSync(CACHE_DIR)) {
  fs.mkdirSync(CACHE_DIR, { recursive: true, mode: 0o755 });
}

function verifyServiceAuth(req) {
  try {
    const serviceId = req.headers['x-service-id'];
    const timestamp = req.headers['x-timestamp'];
    const signature = req.headers['x-signature'];

    if (!serviceId || !timestamp || !signature) return false;

    const secret = SERVICE_SECRETS[serviceId];
    if (!secret) return false;

    // Reject requests with a non-numeric timestamp
    const ts = parseInt(timestamp, 10);
    if (!Number.isFinite(ts)) return false;

    // Reject requests older than 5 minutes
    const age = Date.now() - ts;
    if (age > 300000 || age < -30000) return false;

    const payload = `${serviceId}:${timestamp}:${req.method}:${req.path}`;
    const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex');

    const sigBuf = Buffer.from(signature, 'hex');
    const expBuf = Buffer.from(expected, 'hex');

    // timingSafeEqual throws on differing lengths; guard first to avoid
    // an attacker-controlled crash and to fail closed.
    if (sigBuf.length !== expBuf.length) return false;

    return crypto.timingSafeEqual(sigBuf, expBuf);
  } catch (e) {
    return false;
  }
}

// Model metadata registry
const modelRegistry = new Map();

function sanitizeModelName(name) {
  // Allow alphanumeric, hyphens, underscores, dots
  return name.replace(/[^a-zA-Z0-9._-]/g, '');
}

function resolveModelPath(modelName, version) {
  const safeName = sanitizeModelName(modelName);
  const safeVersion = sanitizeModelName(version);
  return path.join(MODEL_BASE_DIR, safeName, safeVersion, 'model.bin');
}

// Cache layer for model outputs to avoid redundant inference
function getCachePath(modelName, inputHash) {
  const safeName = sanitizeModelName(modelName);
  const cacheFile = `${safeName}_${inputHash}.cache`;
  return path.join(CACHE_DIR, cacheFile);
}

function computeInputHash(input) {
  return crypto.createHash('sha256').update(JSON.stringify(input)).digest('hex').slice(0, 16);
}

// Model loading with caching of resolved paths
const resolvedPathCache = new Map();

function loadModelSafe(modelName, version) {
  const cacheKey = `${modelName}:${version}`;

  let modelPath;
  if (resolvedPathCache.has(cacheKey)) {
    modelPath = resolvedPathCache.get(cacheKey);
  } else {
    modelPath = resolveModelPath(modelName, version);
    resolvedPathCache.set(cacheKey, modelPath);
  }

  // Always verify the resolved path is within MODEL_BASE_DIR before reading
  const resolved = fs.realpathSync(modelPath);
  if (!resolved.startsWith(path.resolve(MODEL_BASE_DIR))) {
    resolvedPathCache.delete(cacheKey);
    throw new Error('Invalid model path');
  }

  return fs.readFileSync(resolved);
}

// Warm cache endpoint - pre-resolves model paths
app.post('/api/v1/warm-cache', (req, res) => {
  if (!verifyServiceAuth(req)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const { models } = req.body;
  if (!Array.isArray(models)) {
    return res.status(400).json({ error: 'models must be an array' });
  }

  const results = [];
  for (const { name, version } of models) {
    try {
      const safeName = sanitizeModelName(name);
      const safeVersion = sanitizeModelName(version);
      const modelPath = path.join(MODEL_BASE_DIR, safeName, safeVersion, 'model.bin');

      // Only allow paths within MODEL_BASE_DIR
      const resolvedCandidate = path.resolve(modelPath);
      if (!resolvedCandidate.startsWith(path.resolve(MODEL_BASE_DIR))) {
        results.push({ name: safeName, version: safeVersion, status: 'error', message: 'Invalid path' });
        continue;
      }

      resolvedPathCache.set(`${safeName}:${safeVersion}`, modelPath);
      results.push({ name: safeName, version: safeVersion, status: 'cached' });
    } catch (e) {
      results.push({ name, version, status: 'error', message: e.message });
    }
  }

  res.json({ results });
});

// Inference endpoint
app.post('/api/v1/infer', (req, res) => {
  if (!verifyServiceAuth(req)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const { model, version, input } = req.body;
  if (!model || !version || !input) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  try {
    const inputHash = computeInputHash(input);
    const cachePath = getCachePath(model, inputHash);

    // Check inference cache
    if (fs.existsSync(cachePath)) {
      const cached = fs.readFileSync(cachePath, 'utf8');
      return res.json({ result: JSON.parse(cached), cached: true });
    }

    // Load model and run inference
    const modelData = loadModelSafe(model, version);

    // Simulated inference
    const result = {
      prediction: Array.from(crypto.randomBytes(4)),
      confidence: 0.95,
      model_size: modelData.length
    };

    // Cache the result
    fs.writeFileSync(cachePath, JSON.stringify(result), { mode: 0o644 });

    res.json({ result, cached: false });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', models_cached: resolvedPathCache.size });
});

const PORT = process.env.PORT || 8080;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`ML Inference server listening on port ${PORT}`);
});
